int NcSkillCount = sizeof(NcSkills)/sizeof(NcSkills[0]);

sNCSKILL *NC_FindCode( unsigned int code )
{
	for( int i=0; i<NcSkillCount; i++ ) if ( NcSkills[i].Code==code ) return &NcSkills[i];
	return 0;
}
sNCSKILL *NC_FindPlay( int play )
{
	if ( !play ) return 0;
	for( int i=0; i<NcSkillCount; i++ ) if ( NcSkills[i].Play==play ) return &NcSkills[i];
	return 0;
}
int NC_Rank( int *arr, int point )
{
	if ( !arr || point<1 || point>10 ) return 0;
	return arr[point-1];
}
